            ('police_api', '안산상록경찰서', 'O0000828', 'esri_police', 'station:100', '2026-11-07 user decision: accept erroneous/shared institution code and use original exact current-custody-name resolution. Scoped key only; no global code override. Existing substation rules preserved.'),
            ('police_api', '부천오정경찰서', 'O0000808', 'esri_police', 'station:97', '2026-11-07 user decision: accept erroneous/shared institution code and use original exact current-custody-name resolution. Scoped key only; no global code override. Existing substation rules preserved.')
        ) as reviewed(item_source_code, current_place, detail_org_id, location_source_code, source_key, evidence_note)
    loop
        select l.id into strict target_id from public.storage_locations l
        where l.location_source_code = rule.location_source_code
          and l.source_key = rule.source_key and l.is_active;
        if exists (select 1 from public.storage_location_detail_mappings m
                   where m.item_source_code = rule.item_source_code
                     and m.normalized_raw_storage_name = rule.current_place
                     and m.detail_org_id = rule.detail_org_id
                     and m.storage_location_id <> target_id) then
            raise exception 'Reviewed mapping conflicts with an existing rule: % / %', rule.current_place, rule.detail_org_id;
        end if;
        insert into public.storage_location_detail_mappings
            (item_source_code, normalized_raw_storage_name, detail_org_id, storage_location_id, evidence_note)
        values (rule.item_source_code, rule.current_place, rule.detail_org_id, target_id, rule.evidence_note)
        on conflict (item_source_code, normalized_raw_storage_name, detail_org_id) do nothing;
    end loop;
end;
